    let rig = Rig::new(&release_commit);
    let first = rig.run(root, &["--format", "json", "release"]);
    assert!(first.status.success(), "{}", stderr(&first));
    let effects = rig.effects();

    for (args, dry_run) in [
        (&["--format", "json", "--dry-run", "release"][..], true),
        (&["--format", "json", "release"][..], false),
