fn planned_bump(package: &str, from: &str, to: &str, writes: Vec<VersionWriteTarget>) -> PlannedBump {
    PlannedBump {
        package: PackageId::parse(package).unwrap(),
        from: cargo_version(from),
        to: cargo_version(to),
        severity: Severity::Minor,
        governed_by: None,
        reason: None,
        writes,
    }
}

