shipped = {'T01', 'T11', 'T02', 'T03', 'T03-PRE', 'T04', 'T03-HISTORY', 'T04-PNPM', 'T04-LOCK', 'T05', 'T10-BINS', 'T10-AUTH'}
d['tasks'] = [t for t in d['tasks'] if t['id'] not in shipped]
