162	                let this_set = claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default();
163	                let promoted_id = PackageId::Prefixed {
164	                    ecosystem: primary_ecosystems[&rel_path],
165	                    name: primary_id.name().to_string(),
166	                };
167	                promoted_siblings
168	                    .entry(primary_id.name().to_string())
169	                    .or_default()
170	                    .push((promoted_id.clone(), this_set));
171	                primary_id = promoted_id;
172	                branch_ii_promoted = true;
173	            }
174	
175	            if !branch_ii_promoted {
176	                index.bare.insert(primary_id.name().to_string(), primary_id.clone());
177	            }
178	
179	            let mut decls = Vec::new();
180	            for (eco, id) in &list {
181	                let (fmt, filename) = match eco {
182	                    Ecosystem::Cargo => (ManifestFormat::CargoToml, "Cargo.toml"),
183	                    Ecosystem::Npm => (ManifestFormat::PackageJson, "package.json"),
184	                    Ecosystem::Pypi => (ManifestFormat::PyprojectToml, "pyproject.toml"),
185	                    _ => (ManifestFormat::PackageJson, "package.json"),
186	                };
187	                let manifest_rel = rel_path.join(filename);
188	                let canonical_decl = ManifestDecl::new(manifest_rel.clone(), ManifestRole::Canonical, fmt).ok();
189	                if let Some(decl) = &canonical_decl {
190	                    decls.push(decl.clone());
191	                }
192	                // For napi platform packages (os + cpu constraints in package.json),
193	                // also push a Platform-role decl so release derivation can route them
194	                // as platform publishes instead of main packages. Reuses
195	                // the canonical decl's manifest handle via the shared
196	                // `manifest_cache` (`npm_role()`) instead of a second, raw
197	                // `fs::read` of the same package.json -- the handle opened here
198	                // is the same one `publish_targets`/`iter_dependencies` reuse
199	                // further down.
200	                if *eco == Ecosystem::Npm {
201	                    let role = canonical_decl
202	                        .as_ref()
203	                        .and_then(|decl| open_cached(manifest_cache, decl, &ctx).ok())
204	                        .and_then(|m| m.npm_role())
205	                        .map(|npm_role| match npm_role {
206	                            callisto_manifests::NpmRole::Platform { platform, arch, abi } => {
207	                                ManifestRole::Platform { platform, arch, abi }
208	                            }
209	                        })
210	                        .unwrap_or(ManifestRole::Canonical);
211	                    if let ManifestRole::Platform { .. } = role {
212	                        if let Ok(platform_decl) = ManifestDecl::new(manifest_rel.clone(), role.clone(), fmt) {
213	                            decls.push(platform_decl);
214	                        }
215	                        // `id` is this manifest's own npm identity, resolved from its
216	                        // own `name` field -- distinct from `primary_id` whenever a
217	                        // higher-priority ecosystem (Cargo) shares this directory.
218	                        // Config authors reference the platform package by
219	                        // its own name in `[[fixed-group]] members`, so that must be
220	                        // the index key; `primary_id` is who it belongs to.
221	                        index
222	                            .platform
223	                            .insert(id.name().to_string(), (primary_id.clone(), manifest_rel, role));
224	                        path_platform_keys
225	                            .entry(rel_path.clone())
226	                            .or_default()
227	                            .push(id.name().to_string());
228	                    }
229	                }
230	                index.native.insert((*eco, id.name().to_string()), primary_id.clone());
231	                if id.name() == primary_id.name() {
232	                    index.prefixed.insert((*eco, id.name().to_string()), primary_id.clone());
233	                }
234	            }
235	
236	            let current_decls = decls.clone();
237	            if let Some((existing_path, existing_decls)) =
238	                package_manifest_decls.insert(primary_id.clone(), (rel_path.clone(), decls))
239	            {
240	                // Both paths' claiming ecosystems are guaranteed disjoint here: an
241	                // overlap would already have failed at the native_owner check above.
242	                let name = primary_id.name().to_string();
243	                // STALE-KEY REWRITE location (4): re-key package_manifest_decls under
244	                // each path's own newly-promoted Prefixed id, sourcing each path's own
245	                // decls -- captured via the `existing_decls` returned by `insert` above
246	                // and the `current_decls` clone taken before `insert` overwrote the map,
247	                // never via a `.get(&primary_id)` lookup after the fact (a lookup miss
248	                // there would silently substitute an empty Vec -- the
249	                // manifests-bleed bug).
250	                let existing_id = PackageId::Prefixed {
251	                    ecosystem: primary_ecosystems[&existing_path],
252	                    name: name.clone(),
253	                };
254	                let current_id = PackageId::Prefixed {
255	                    ecosystem: primary_ecosystems[&rel_path],
256	                    name: name.clone(),
257	                };
258	                package_manifest_decls.insert(existing_id.clone(), (existing_path.clone(), existing_decls));
259	                package_manifest_decls.insert(current_id.clone(), (rel_path.clone(), current_decls));
260	                package_manifest_decls.remove(&primary_id);
261	                // STALE-KEY REWRITE location (1): once a bare name is promoted,
262	                // it MUST NOT remain in index.bare.
263	                index.bare.remove(&name);
264	                // STALE-KEY REWRITE location (2): update index.native values
265	                // for all native keys declared by either path so they map to
266	                // their path's newly-promoted Prefixed id, not the stale primary_id.
267	                if let Some(keys) = path_native_keys.get(&existing_path) {
268	                    for key in keys {
269	                        index.native.insert(key.clone(), existing_id.clone());
270	                    }
271	                }
272	                if let Some(keys) = path_native_keys.get(&rel_path) {
273	                    for key in keys {
274	                        index.native.insert(key.clone(), current_id.clone());
275	                    }
276	                }
277	                // STALE-KEY REWRITE location (3)/(5): update index.prefixed values
278	                // for the primary identities so they point to the newly-promoted
279	                // Prefixed id rather than the pre-promotion primary_id.
280	                for eco in claiming_ecosystems.get(&existing_path).cloned().unwrap_or_default() {
281	                    index.prefixed.insert((eco, name.clone()), existing_id.clone());
282	                }
283	                for eco in claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default() {
284	                    index.prefixed.insert((eco, name.clone()), current_id.clone());
285	                }
286	                // STALE-KEY REWRITE location (6): update index.platform's owner-id
287	                // component for every platform manifest declared under either path,
288	                // so a platform sibling co-located with a promoted owner keeps
289	                // pointing at that owner's newly-promoted Prefixed id rather than
290	                // the stale pre-promotion primary_id.
291	                if let Some(keys) = path_platform_keys.get(&existing_path) {
292	                    for key in keys {
293	                        if let Some((_, manifest_rel, role)) = index.platform.get(key).cloned() {
294	                            index
295	                                .platform
296	                                .insert(key.clone(), (existing_id.clone(), manifest_rel, role));
297	                        }
298	                    }
299	                }
300	                if let Some(keys) = path_platform_keys.get(&rel_path) {
301	                    for key in keys {
302	                        if let Some((_, manifest_rel, role)) = index.platform.get(key).cloned() {
303	                            index
304	                                .platform
305	                                .insert(key.clone(), (current_id.clone(), manifest_rel, role));
306	                        }
307	                    }
308	                }
309	                let existing_set = claiming_ecosystems.get(&existing_path).cloned().unwrap_or_default();
310	                let current_set = claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default();
311	                promoted_siblings
312	                    .entry(name.clone())
313	                    .or_default()
314	                    .extend([(existing_id, existing_set), (current_id, current_set)]);
315	            }
316	        }
317	
318	        // After the loop so the owner's id is final (post-promotion).
319	        for (platform_dir, (owner_dir, name, role)) in attached_platforms {
320	            let manifest_rel = platform_dir.join("package.json");
321	            let owner = package_manifest_decls.iter_mut().find(|(_, (path, decls))| {
322	                *path == owner_dir && decls.iter().any(|d| d.format == ManifestFormat::PackageJson)
323	            });
324	            let (Some((owner_id, (_, decls))), Ok(decl)) = (
325	                owner,
326	                ManifestDecl::new(manifest_rel.clone(), role.clone(), ManifestFormat::PackageJson),
327	            ) else {
328	                continue;
329	            };
330	            decls.push(decl);
331	            index.platform.insert(name, (owner_id.clone(), manifest_rel, role));
332	        }
333	
334	        let cfg = cfg.with_promoted_siblings(promoted_siblings);
335	
336	        // Tracks, per cfg.package_sets entry (by index), whether it matched at
337	        // least one real discovered package during this walk. A [[package-set]]
338	        // rule that matches nothing is almost always a typo or a stale
339	        // ecosystem prefix (see PackageSetMatchedNothing below) rather than
340	        // intentional, so it must be surfaced instead of silently ignored.
341	        let mut package_set_matched = vec![false; cfg.package_sets.len()];
342	
343	        // Same tracking, for `[[package]]` rules: an exact-id rule that matches zero real
344	        // packages (e.g. an ecosystem prefix the package doesn't actually have) is just as
345	        // likely a typo as an empty `[[package-set]]` glob, so it gets the same diagnostic.
346	        let mut package_rule_matched = vec![false; cfg.packages.len()];
347	
348	        let mut packages = BTreeMap::new();
349	        for (id, (rel_path, decls)) in package_manifest_decls {
350	            let ch_path = rel_path.join("CHANGELOG.md");
351	            let mut publish_to = Vec::new();
352	            // Attached platform manifests publish as their owner's platform operations, not as targets.
353	            for decl in decls.iter().filter(|d| d.role == ManifestRole::Canonical) {
354	                if let Ok(editor) = open_cached(manifest_cache, decl, &ctx) {
355	                    for target in editor.publish_targets() {
356	                        if target != PublishTarget::None && !publish_to.contains(&target) {
357	                            publish_to.push(target);
358	                        }
359	                    }
360	                }
361	            }
362	            if publish_to.is_empty() {
363	                publish_to.push(PublishTarget::None);
364	            }
365	
366	            // The real ecosystem(s) this package's manifests were discovered
367	            // in. `id` may be PackageId::Bare (unpromoted) or PackageId::Prefixed
368	            // (promoted); this is the
369	            // only place an ecosystem-prefixed [[package-set]] pattern has
370	            // anything to match against.
371	            let package_ecosystems: Vec<Ecosystem> = decls.iter().map(|d| d.ecosystem()).collect();
372	
373	            // Two-pass specificity search for [[package]] rules.
374	            // Pass 1: find the first Prefixed rule (pattern.ecosystem().is_some())
375	            //         that matches this package's ID. Prefixed rules always win
376	            //         over Bare rules regardless of declaration order in callisto.toml.
377	            // Pass 2: only if pass 1 found nothing, find the first Bare rule
378	            //         (any rule, since no Prefixed rule matched, the first match
379	            //          is necessarily Bare) that matches this package's ID.
380	            // Within each pass, first-match-wins (TOML declaration order) applies.
381	            let pkg_override = resolve_package_config(&id, &package_ecosystems, &cfg)?;
382	
383	            // Record which [[package-set]] patterns match this package,
384	            // independent of whether a [[package]] rule ends up shadowing the
385	            // fallback below — a pattern that is always shadowed still
386	            // "matched" for the purpose of the zero-match diagnostic.
387	            for (idx, (pattern, _)) in cfg.package_sets.iter().enumerate() {
388	                if pattern.matches_in_ecosystems(id.name(), &package_ecosystems) {
389	                    package_set_matched[idx] = true;
390	                }
391	            }
392	            for (idx, (rule_id, _)) in cfg.packages.iter().enumerate() {
393	                if rule_applies(rule_id, &id, &package_ecosystems) {
394	                    package_rule_matched[idx] = true;
395	                }
396	            }
397	
398	            // If no [[package]] rule matched, look for a [[package-set]] fallback.
399	            // [[package-set]] uses glob patterns and can match many packages at once;
400	            // [[package]] always takes priority over [[package-set]] for the same package.

