export const meta = {
  name: 'wave0-callisto',
  description: 'Wave 0: W4 diagnostic-path audit and wire-compatibility matrix (each with an independent verifier) plus the W1 CI attestation job in its own worktree',
  phases: [
    { title: 'Investigate', detail: 'W4 audit and wire matrix, read-only' },
    { title: 'Verify', detail: 'skeptical re-check of every cited location' },
    { title: 'W1 lane', detail: 'CI job that verifies the latest release asset attestation' },
  ],
}

