    },
    indistinguishable_failures: {
      type: 'array',
      description: 'provider failures that currently collapse into one cause (e.g. auth vs transport)',
      items: {
        type: 'object',
        properties: {
          what: { type: 'string' },
          collapsed_into: { type: 'string' },
          location: { type: 'string' },
        },
        required: ['what', 'collapsed_into', 'location'],
