    proposed_closed_causes: {
      type: 'array',
      description: 'minimal additions to ProviderIndeterminateCause (or an equivalent closed type) with where each would be classified',
      items: {
        type: 'object',
        properties: { name: { type: 'string' }, classified_at: { type: 'string' }, why: { type: 'string' } },
        required: ['name', 'classified_at', 'why'],
      },
    },
    persisted_today: { type: 'string', description: 'which of these outputs are written to a durable file today, and which are not' },
    unknowns: { type: 'array', items: { type: 'string' } },
  },
  required: ['paths', 'indistinguishable_failures', 'proposed_closed_causes', 'persisted_today'],
}

const WIRE_SCHEMA = {
  type: 'object',
  properties: {
    documents: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          writer_version: { type: 'string' },
          readable_versions: { type: 'array', items: { type: 'string' } },
          digest_or_binding: { type: 'string', description: 'what digest or hash covers it and whether nested document versions are validated' },
          semantic_changes_between_versions: { type: 'string' },
          old_document_policy: { type: 'string', description: 'what happens when an older or newer document is read: accepted, migrated, or rejected, and with which error code/diagnostic' },
          readers_and_writers: { type: 'array', items: { type: 'string' }, description: 'commands, scripts and code paths that read or write it' },
          evidence: { type: 'array', items: { type: 'string' }, description: 'file:line' },
        },
        required: ['name', 'writer_version', 'readable_versions', 'old_document_policy', 'evidence'],
