  },
  required: ['documents', 'old_intent_rerun', 'gaps'],
}

const VERIFY_SCHEMA = {
  type: 'object',
  properties: {
    checked: { type: 'number' },
    wrong: {
      type: 'array',
      items: {
        type: 'object',
        properties: { claim: { type: 'string' }, actual: { type: 'string' }, evidence: { type: 'string' } },
